 public_key_ring ring={p->p0,p->p1};
 for(int i=0;i<NR;++i){Report*r=&p->reports[i];randomize(r->msg,32);randomize(r->nonce,32);uint8_t ti[2][32],ctx[32],seed[64];taginputs(p,r,(uint8_t*)ti);int k=i>=5;sk->idx=k?other:honest;check("prepare report key",faest_unpack_secret_key_fixed_owf_inputs(sk,keys[k],ins[0],ins[1]));check("prepare nonce-specific report tags",faest_unpack_secret_key_for_tag_alt(sk,ti[0],ti[1]));r->t0=sk->tag;r->t1=sk->tag1;signctx(p,r,ctx);randomize(seed,64);double t=now();check("anonymous report signing",faest_tagged_ring_sign(r->proof,ctx,32,sk,&ring,&r->t0,&r->t1,seed,64));sign_ms[i]=now()-t;t=now();check("anonymous report verification",rv(p,r));verify_ms[i]=now()-t;}
 /* Cheap approaches that must NOT count as successful EX-01/EX-02. */
 uint8_t naive[FAEST_SIGNATURE_BYTES],packed[FAEST_SECRET_KEY_BYTES],pkpacked[FAEST_PUBLIC_KEY_BYTES],digest[32],seed[64];memcpy(packed,ins[0],FAEST_IV_BYTES);memcpy(packed+FAEST_IV_BYTES,keys[1],32);reportid(p,&p->reports[0],digest);randomize(seed,64);check("naive non-signer signs original digest",faest_sign(naive,digest,32,packed,seed,64));faest_pack_public_key(pkpacked,&p->p0[other]);check("counterexample membership-only claim accepts non-signer",faest_verify(naive,digest,32,pkpacked));
 uint8_t eventin[32];randomize(eventin,32);public_key event0,event3;derive(&event0,sk,keys[0],eventin);derive(&event3,sk,keys[0],eventin);check("counterexample fixed-event label links unselected reports",!memcmp(event0.owf_output,event3.owf_output,32));
 p->claimant=honest;uint8_t ctx[32];claimctx(p,&p->reports[0],honest,ctx);prep(sk,keys[0],&p->p0[honest],&p->p1[honest],&p->reports[0].t0,&p->reports[0].t1);double t=now();tp(p->claim,sk,ctx,&p->p0[honest],&p->p1[honest],&p->reports[0].t0,&p->reports[0].t1);claim_ms=now()-t;t=now();check("EX01 actual signer claims original signature",cv(p,&p->reports[0],honest,p->claim));claim_verify_ms=now()-t;
 check("EX01 wrong claimed identity rejected",!cv(p,&p->reports[0],other,p->claim));check("EX01 proof transplanted to another report rejected",!cv(p,&p->reports[1],honest,p->claim));
 uint8_t*attack=aalloc(FAEST_TAGGED_RING_SIGNATURE_BYTES);claimctx(p,&p->reports[0],other,ctx);prep(sk,keys[1],&p->p0[other],&p->p1[other],&p->reports[0].t0,&p->reports[0].t1);tp(attack,sk,ctx,&p->p0[other],&p->p1[other],&p->reports[0].t0,&p->reports[0].t1);check("EX01 full hostile proof from non-signer rejected",!cv(p,&p->reports[0],other,attack));
 claimctx(p,&p->reports[5],honest,ctx);prep(sk,keys[1],&p->p0[honest],&p->p1[honest],&p->reports[5].t0,&p->reports[5].t1);tp(attack,sk,ctx,&p->p0[honest],&p->p1[honest],&p->reports[5].t0,&p->reports[5].t1);check("EX01 malicious signer cannot frame honest identity",!cv(p,&p->reports[5],honest,attack));
