 Link*l=&p->link;l->ids[0]=0;l->ids[1]=1;l->ids[2]=2;uint8_t tauin[64];do {randomize(tauin,64);for(int b=0;b<4;++b)tauin[16*b]=(tauin[16*b]&63)|128;derive(&l->tau,sk,keys[0],tauin);derive(&l->tau1,sk,keys[0],tauin+32);}while(!distinct_tau(p,l));linkctx(p,l,ctx);t=now();for(int i=0;i<NS;++i){const Report*r=&p->reports[l->ids[i]];prep(sk,keys[0],&r->t0,&r->t1,&l->tau,&l->tau1);tp(l->proofs[i],sk,ctx,&r->t0,&r->t1,&l->tau,&l->tau1);}link_ms=now()-t;t=now();check("EX02 selected three signatures link anonymously",lv(p,l));link_verify_ms=now()-t;
 Link*bad=aalloc(sizeof(Link));*bad=*l;bad->ids[2]=3;check("EX02 same-signer unselected report cannot be appended by reusing proof",!lv(p,bad));*bad=*l;bad->ids[2]=5;check("EX02 other-signer signature cannot replace selected one",!lv(p,bad));*bad=*l;bad->ids[2]=bad->ids[0];check("EX02 duplicate selected signature rejected",!lv(p,bad));*bad=*l;uint32_t x=bad->ids[0];bad->ids[0]=bad->ids[1];bad->ids[1]=x;check("EX02 selected-set order tampering rejected",!lv(p,bad));*bad=*l;((uint8_t*)bad->tau.owf_output)[0]^=1;check("EX02 shared link output substitution rejected",!lv(p,bad));*bad=*l;((uint8_t*)bad->tau.owf_input)[16]^=1;check("EX02 link second input block substitution rejected",!lv(p,bad));
