 *bad=*l;bad->tau=p->p0[honest];check("EX02 known identity public inputs forbidden as link challenge",!lv(p,bad));*bad=*l;bad->tau=p->reports[3].t0;check("EX02 unselected report public inputs forbidden as link challenge",!lv(p,bad));
